// ============================================================
// Климат-контроль на ESP32 (ESP-WROOM-32)
// Модуль кнопок: K845037 (аналоговый, 1 пин)
// Датчики: BME280 (I2C), DS18B20 (OneWire)
// Дисплей: SSD1306 (I2C)
// Веб-интерфейс + сохранение настроек в NVS
// ============================================================

#include <Wire.h>
#include <Adafruit_BME280.h>
#include <Adafruit_SSD1306.h>
#include <OneWire.h>
#include <DallasTemperature.h>
#include <WiFi.h>
#include <WebServer.h>
#include <Preferences.h>

// --- Пины ---
#define RELAY_COMPRESSOR_PIN  16
#define RELAY_FAN_PIN           4
#define RELAY_SOLENOID_PIN    26
#define EVAP_TEMP_PIN         25
#define LED_PIN                2
#define BTN_ANALOG_PIN        35   // K845037 Signal

// --- I2C ---
#define SCREEN_WIDTH          128
#define SCREEN_HEIGHT          64
#define OLED_ADDR            0x3C
#define BME_ADDR             0x76

// --- Wi-Fi ---
const char* WIFI_SSID     = "YOUR_SSID";
const char* WIFI_PASSWORD = "YOUR_PASSWORD";

// --- Пороги по умолчанию ---
float humidityHigh     = 60.0;
float humidityLow      = 45.0;
float tempLow          = 18.0;
float tempHigh         = 26.0;
float minRoomTemp      = 10.0;
float defrostStartTemp = -1.0;
float defrostEndTemp   =  6.0;

// --- Тайминги ---
const unsigned long COMPRESSOR_MIN_OFF  = 180000; // 3 минуты
const unsigned long COMPRESSOR_MIN_RUN  = 60000;  // 1 минута
const unsigned long FAN_POST_RUN        = 30000;  // 30 секунд продувки
const unsigned long FAN_PRESTART        = 2000;   // 2 секунды перед компрессором
const unsigned long DEFROST_MAX_TIME    = 600000; // 10 минут
const unsigned long DEFROST_INTERVAL    = 2700000;// 45 минут

// --- Объекты ---
Adafruit_BME280 bme;
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, -1);
WebServer server(80);
Preferences prefs;
OneWire oneWire(EVAP_TEMP_PIN);
DallasTemperature evapSensor(&oneWire);

// --- Состояния ---
float currentHumidity = 0;
float currentTemp     = 0;
float evapTemp        = 0;

bool compressorRunning = false;
bool fanRunning       = false;
bool manualMode       = false;
bool defrosting       = false;
bool fanStopping      = false;

unsigned long compressorOnTime  = 0;
unsigned long compressorOffTime = 0;
unsigned long fanStopTimer      = 0;
unsigned long defrostStartTime  = 0;

// --- Меню ---
int menuIndex = 0;
const int MENU_ITEMS = 7;
const char* menuNames[MENU_ITEMS] = {
  "Влаж ВКЛ", "Влаж ВЫКЛ", "Темп ВКЛ", "Темп ВЫКЛ",
  "Мин.Т", "Отт.старт", "Отт.стоп"
};
float* menuValues[MENU_ITEMS] = {
  &humidityHigh, &humidityLow, &tempLow, &tempHigh,
  &minRoomTemp, &defrostStartTemp, &defrostEndTemp
};
const float menuStep[MENU_ITEMS] = { 1.0, 1.0, 0.5, 0.5, 0.5, 0.5, 0.5 };
const float menuMin[MENU_ITEMS]  = { 10, 5, -10, 5, 0, -10, 0  };
const float menuMax[MENU_ITEMS]  = { 95, 90, 40, 50, 20, 5, 20  };

// --- Кнопки K845037 ---
enum AnalogButton : int {
  BTN_NONE    = 0,
  BTN_MENU    = 1,
  BTN_UP      = 2,
  BTN_DOWN    = 3,
  BTN_AUTO    = 4,
  BTN_START   = 5
};

const int BTN_THRESHOLDS[6] = {
  4095,        // нет кнопки
  800,         // KEY1: 0–800    → Меню
  1600,        // KEY2: 800–1600 → Плюс
  2400,        // KEY3: 1600–2400→ Минус
  3200,        // KEY4: 2400–3200→ Авто/Ручной
  4095         // KEY5: 3200–4095→ Пуск/Стоп
};

int lastBtn = BTN_NONE;
unsigned long lastBtnDebounce = 0;
const unsigned long BTN_DEBOUNCE = 200;

// --- Таймеры ---
unsigned long lastSensorRead     = 0;
const unsigned long SENSOR_INTERVAL   = 3000;
unsigned long lastDisplayUpdate  = 0;
const unsigned long DISPLAY_INTERVAL  = 500;
unsigned long lastEvapRead       = 0;
const unsigned long EVAP_INTERVAL    = 5000;

// --- Сохранение ---
bool needSave = false;
unsigned long saveTimer = 0;
const unsigned long SAVE_DELAY = 2000;

// ============================================================
// NVS: загрузка и сохранение
// ============================================================
void loadPrefs() {
  prefs.begin("climate", true);
  humidityHigh     = prefs.getFloat("hum_hi", humidityHigh);
  humidityLow      = prefs.getFloat("hum_lo", humidityLow);
  tempLow          = prefs.getFloat("tmp_lo", tempLow);
  tempHigh         = prefs.getFloat("tmp_hi", tempHigh);
  minRoomTemp      = prefs.getFloat("tmp_min", minRoomTemp);
  defrostStartTemp = prefs.getFloat("def_s", defrostStartTemp);
  defrostEndTemp   = prefs.getFloat("def_e", defrostEndTemp);
  prefs.end();
  Serial.printf("NVS: H %.0f/%.0f T %.1f/%.1f MinT %.1f Defrost %.1f/%.1f\n",
    humidityLow, humidityHigh, tempLow, tempHigh,
    minRoomTemp, defrostStartTemp, defrostEndTemp);
}

void savePrefs() {
  prefs.begin("climate", false);
  prefs.putFloat("hum_hi", humidityHigh);
  prefs.putFloat("hum_lo", humidityLow);
  prefs.putFloat("tmp_lo", tempLow);
  prefs.putFloat("tmp_hi", tempHigh);
  prefs.putFloat("tmp_min", minRoomTemp);
  prefs.putFloat("def_s",   defrostStartTemp);
  prefs.putFloat("def_e",   defrostEndTemp);
  prefs.end();
  Serial.println("Пороги сохранены в NVS");
}

void triggerSave() {
  needSave = true;
  saveTimer = millis();
}

// ============================================================
// Чтение аналоговых кнопок K845037
// ============================================================
int readAnalogButton() {
  int sum = 0;
  for (int i = 0; i < 3; i++) {
    sum += analogRead(BTN_ANALOG_PIN);
    delay(2);
  }
  int avg = sum / 3;

  if (avg > 4000) return BTN_NONE;
  for (int i = 1; i <= 5; i++) {
    if (avg <= BTN_THRESHOLDS[i]) return i;
  }
  return BTN_NONE;
}

void handleAnalogButtons() {
  int btn = readAnalogButton();
  unsigned long now = millis();

  // Антидребезг
  if (btn != lastBtn && (now - lastBtnDebounce >= BTN_DEBOUNCE)) {
    lastBtnDebounce = now;
    lastBtn = btn;

    switch (btn) {
      case BTN_MENU:
        menuIndex = (menuIndex + 1) % MENU_ITEMS;
        Serial.print("Меню: "); Serial.println(menuNames[menuIndex]);
        break;
      case BTN_UP:
        *menuValues[menuIndex] += menuStep[menuIndex];
        if (*menuValues[menuIndex] > menuMax[menuIndex])
          *menuValues[menuIndex] = menuMax[menuIndex];
        triggerSave();
        Serial.print("Увеличено: "); Serial.println(*menuValues[menuIndex]);
        break;
      case BTN_DOWN:
        *menuValues[menuIndex] -= menuStep[menuIndex];
        if (*menuValues[menuIndex] < menuMin[menuIndex])
          *menuValues[menuIndex] = menuMin[menuIndex];
        triggerSave();
        Serial.print("Уменьшено: "); Serial.println(*menuValues[menuIndex]);
        break;
      case BTN_AUTO:
        manualMode = !manualMode;
        Serial.print("Режим: "); Serial.println(manualMode ? "Ручной" : "Авто");
        break;
      case BTN_START:
        if (manualMode) {
          if (compressorRunning || defrosting) {
            stopCompressor();
          } else {
            startCompressor();
          }
        }
        break;
    }
  }
}

// ============================================================
// Setup
// ============================================================
void setup() {
  Serial.begin(115200);
  Serial.println("\n=== Климат-контроль (K845037) ===");

  pinMode(RELAY_COMPRESSOR_PIN, OUTPUT);
  pinMode(RELAY_FAN_PIN, OUTPUT);
  pinMode(RELAY_SOLENOID_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(RELAY_COMPRESSOR_PIN, LOW);
  digitalWrite(RELAY_FAN_PIN, LOW);
  digitalWrite(RELAY_SOLENOID_PIN, LOW);
  digitalWrite(LED_PIN, LOW);

  analogReadResolution(12);  // 12-бит АЦП

  Wire.begin(21, 22);

  loadPrefs();

  if (!bme.begin(BME_ADDR)) {
    Serial.println("BME280 не найден!");
  } else {
    Serial.println("BME280 OK");
  }

  evapSensor.begin();
  evapSensor.setResolution(12);
  Serial.println("DS18B20 OK");

  if (!display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDR)) {
    Serial.println("SSD1306 не найден!");
  } else {
    display.clearDisplay();
    display.setTextColor(SSD1306_WHITE);
    display.setTextSize(1);
    display.setCursor(15, 20);
    display.print("Климат-контроль");
    display.setCursor(30, 35);
    display.print("Запуск...");
    display.display();
  }

  WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
  Serial.print("Wi-Fi");
  int attempts = 0;
  while (WiFi.status() != WL_CONNECTED && attempts < 30) {
    delay(500);
    Serial.print(".");
    attempts++;
  }
  if (WiFi.status() == WL_CONNECTED) {
    Serial.printf("\nIP: %s\n", WiFi.localIP().toString().c_str());
  } else {
    Serial.println("\nWi-Fi не подключён — работаем офлайн");
  }

  server.on("/",       handleRoot);
  server.on("/toggle", handleToggle);
  server.on("/auto",   handleAuto);
  server.on("/status", handleStatus);
  server.on("/set",    handleSet);
  server.begin();

  updateSensors();
  updateEvapTemp();
  updateDisplay();
  delay(1500);
}

// ============================================================
// Loop
// ============================================================
void loop() {
  server.handleClient();
  handleAnalogButtons();

  if (needSave && millis() - saveTimer >= SAVE_DELAY) {
    savePrefs();
    needSave = false;
  }

  if (millis() - lastSensorRead >= SENSOR_INTERVAL) {
    lastSensorRead = millis();
    updateSensors();
    if (!manualMode) {
      controlSystem();
    }
  }

  if (millis() - lastEvapRead >= EVAP_INTERVAL) {
    lastEvapRead = millis();
    updateEvapTemp();
    if (!manualMode && defrosting) {
      checkDefrostEnd();
    }
  }

  if (fanStopping && millis() - fanStopTimer >= FAN_POST_RUN) {
    digitalWrite(RELAY_FAN_PIN, LOW);
    fanRunning = false;
    fanStopping = false;
    Serial.println("Вентилятор ВЫКЛ (продувка окончена)");
  }

  if (millis() - lastDisplayUpdate >= DISPLAY_INTERVAL) {
    lastDisplayUpdate = millis();
    updateDisplay();
  }

  digitalWrite(LED_PIN, (compressorRunning || defrosting) ? HIGH : LOW);
}

// ============================================================
// Датчики
// ============================================================
void updateSensors() {
  currentHumidity = bme.readHumidity();
  currentTemp     = bme.readTemperature();
  if (isnan(currentHumidity) || isnan(currentTemp)) {
    Serial.println("Ошибка BME280");
    return;
  }
  Serial.printf("H: %.1f%%  T: %.1f°C  Tисп: %.1f°C\n",
    currentHumidity, currentTemp, evapTemp);
}

void updateEvapTemp() {
  evapSensor.requestTemperatures();
  float t = evapSensor.getTempCByIndex(0);
  if (t != DEVICE_DISCONNECTED_C && !isnan(t)) {
    evapTemp = t
